-- 비상 초5 영어 Lesson 1 개정: 철자 문항 보강, 5차시·3차시 글 활동을 핵심 표현(출신·이름 철자) 안으로 정리, 6차시에 새 상황 문항. content/l1 에서 생성(gen2.cjs).
-- 바뀐 12개 단계의 기존 문항을 지우고 새 문항을 초안(draft)으로 넣는다. 승인·재발행은 따로.
do $do$
declare v_unit uuid; v_cnt int; v_del int; v_n int; v_miss int;
begin
  select count(*), min(u.id::text)::uuid into v_cnt, v_unit from units u join books b on b.id = u.book_id where u.no = 1 and u.kind = 'lesson' and b.grade = 5 and b.title = '초5 영어';
  if v_cnt <> 1 then raise exception 'L1 unit lookup: % match(es)', v_cnt; end if;
  create temp table _r on commit drop as select * from jsonb_to_recordset($j$[{"lesson":3,"pos":7,"n":0,"kind":"saykor","tag":"speak","payload":{"tag":"speak","target":"Where are you from?","k":"saykor","ko":"너는 어느 나라에서 왔니?","koHl":"어느 나라"}},{"lesson":3,"pos":7,"n":1,"kind":"saykor","tag":"speak","payload":{"tag":"speak","target":"I'm from Korea.","k":"saykor","ko":"나는 한국에서 왔어.","koHl":"한국"}},{"lesson":3,"pos":7,"n":2,"kind":"saykor","tag":"speak","payload":{"tag":"speak","target":"How do you spell your name?","k":"saykor","ko":"너의 이름은 철자가 어떻게 되니?","koHl":"철자"}},{"lesson":3,"pos":7,"n":3,"kind":"saykor","tag":"speak","payload":{"tag":"speak","target":"H-A-N-A.","k":"saykor","ko":"내 이름 철자는 H-A-N-A야.","koHl":"H-A-N-A"}},{"lesson":3,"pos":7,"n":4,"kind":"saykor","tag":"speak","payload":{"tag":"speak","target":"L-E-O.","k":"saykor","ko":"내 이름 철자는 L-E-O야.","koHl":"L-E-O"}},{"lesson":3,"pos":7,"n":5,"kind":"saykor","tag":"speak","payload":{"tag":"speak","target":"I'm from the U.S.","k":"saykor","ko":"나는 미국에서 왔어.","koHl":"미국"}},{"lesson":3,"pos":10,"n":0,"kind":"mtext","tag":"read","payload":{"tag":"read","k":"mtext","title":"Name Card","text":["Hello. My name is [[Leo]].","[[L-E-O]].","I'm from [[Brazil]].","Nice to meet you."],"explain":["먼저 {{이름}}을 말하며 인사합니다.","이름의 {{철자}}를 알파벳 하나씩 말합니다.","{{어느 나라}}에서 왔는지 말합니다.","처음 만난 친구에게 인사합니다."],"ko":"안녕. 내 이름은 레오야.\nL-E-O야.\n나는 브라질에서 왔어.\n만나서 반가워."}},{"lesson":3,"pos":10,"n":1,"kind":"mtext","tag":"read","payload":{"tag":"read","k":"mtext","title":"Name Card","text":["Hello. My name is [[Zoe]].","[[Z-O-E]].","I'm from the [[U.S.]].","Nice to meet you."],"explain":["먼저 {{이름}}을 말하며 인사합니다.","이름의 {{철자}}를 알파벳 하나씩 말합니다.","{{어느 나라}}에서 왔는지 말합니다.","처음 만난 친구에게 인사합니다.","미국은 the U.S. 처럼 the 를 붙여요."],"ko":"안녕. 내 이름은 조이야.\nZ-O-E야.\n나는 미국에서 왔어.\n만나서 반가워."}},{"lesson":3,"pos":11,"n":0,"kind":"sqtf","tag":"read","payload":{"tag":"read","pic":"brazil","title":"Name Card","text":["Hello. My name is Leo.","L-E-O.","I'm from Brazil.","Nice to meet you."],"ko":"안녕. 내 이름은 레오야.\nL-E-O야.\n나는 브라질에서 왔어.\n만나서 반가워.","k":"sqtf","items":[{"t":"Leo is from Brazil.","a":true},{"t":"Leo is from Egypt.","a":false},{"t":"Leo's name is L-E-O.","a":true}]}},{"lesson":3,"pos":11,"n":1,"kind":"sqtf","tag":"read","payload":{"tag":"read","pic":"us","title":"Name Card","text":["Hello. My name is Zoe.","Z-O-E.","I'm from the U.S..","Nice to meet you."],"ko":"안녕. 내 이름은 조이야.\nZ-O-E야.\n나는 미국에서 왔어.\n만나서 반가워.","k":"sqtf","items":[{"t":"Zoe is from the U.S.","a":true},{"t":"Zoe is from Brazil.","a":false},{"t":"Zoe's name is Z-O-E.","a":true}]}},{"lesson":3,"pos":13,"n":0,"kind":"mfree","tag":"write","payload":{"tag":"write","k":"mfree","topic":"korea","topicLabel":"나라","lines":["Hello. My name is {}.","{}.","I'm from {}."],"lineHints":["내 이름을 써요. (예: Hana)","내 이름의 철자를 알파벳 하나씩 - 로 이어 써요. (예: H-A-N-A)","나라 이름은 대문자로 시작해요. (예: Korea)"],"hint":["Hello. My name is Hana."]}},{"lesson":3,"pos":13,"n":1,"kind":"mfree","tag":"write","payload":{"tag":"write","k":"mfree","topic":"brazil","topicLabel":"나라","lines":["Hi, I'm {}.","{}.","I'm from {}."],"lineHints":["내 이름을 써요. (예: Leo)","내 이름의 철자를 알파벳 하나씩 - 로 이어 써요. (예: L-E-O)","나라 이름은 대문자로 시작해요. (예: Brazil)"],"hint":["Hi, I'm Leo."]}},{"lesson":4,"pos":0,"n":0,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"너는 어느 나라에서 왔니?","tpl":"Where {} you from?","ans":"are"}},{"lesson":4,"pos":0,"n":1,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"나는 프랑스에서 왔어.","tpl":"I'm {} France.","ans":"from"}},{"lesson":4,"pos":0,"n":2,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"나는 브라질에서 왔어.","tpl":"I'm from {}.","ans":"Brazil"}},{"lesson":4,"pos":0,"n":3,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"너의 이름은 철자가 어떻게 되니?","tpl":"How do you {} your name?","ans":"spell"}},{"lesson":4,"pos":0,"n":4,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"나는 한국에서 왔어.","tpl":"I'm from {}.","ans":"Korea"}},{"lesson":4,"pos":0,"n":5,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"너는 어느 나라에서 왔니?","tpl":"Where are {} from?","ans":"you"}},{"lesson":4,"pos":0,"n":6,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"내 이름의 철자를 말해요. (Leo)","tpl":"{}.","ans":"L-E-O"}},{"lesson":4,"pos":0,"n":7,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"나는 미국에서 왔어.","tpl":"I'm from the {}.","ans":"U.S."}},{"lesson":4,"pos":0,"n":8,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"내 이름의 철자를 말해요. (Amir)","tpl":"{}.","ans":"A-M-I-R"}},{"lesson":4,"pos":0,"n":9,"kind":"sfill","tag":"write","payload":{"tag":"write","k":"sfill","ko":"만나서 반가워.","tpl":"Nice to {} you.","ans":"meet"}},{"lesson":5,"pos":1,"n":0,"kind":"mtext","tag":"read","payload":{"tag":"read","k":"mtext","title":"My Hero","text":["My name is [[Max]].","[[M-A-X]].","I'm from [[Brazil]].","Nice to meet you."],"explain":["먼저 {{이름}}을 말합니다.","이름의 {{철자}}를 알파벳 하나씩 말합니다.","{{출신 나라}}를 말합니다.","처음 만난 친구에게 인사합니다."],"ko":"내 이름은 맥스야.\nM-A-X야.\n나는 브라질에서 왔어.\n만나서 반가워."}},{"lesson":5,"pos":1,"n":1,"kind":"mtext","tag":"read","payload":{"tag":"read","k":"mtext","title":"My Hero","text":["My name is [[Zia]].","[[Z-I-A]].","I'm from [[Egypt]].","Nice to meet you."],"explain":["먼저 {{이름}}을 말합니다.","이름의 {{철자}}를 알파벳 하나씩 말합니다.","{{출신 나라}}를 말합니다.","처음 만난 친구에게 인사합니다."],"ko":"내 이름은 지아야.\nZ-I-A야.\n나는 이집트에서 왔어.\n만나서 반가워."}},{"lesson":5,"pos":2,"n":0,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ko":"내 이름은 맥스야.","ans":"My name is Max.","extra":["is a"]}},{"lesson":5,"pos":2,"n":1,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ko":"나는 브라질에서 왔어.","ans":"I'm from Brazil.","extra":["in"]}},{"lesson":5,"pos":2,"n":2,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ko":"너의 이름은 철자가 어떻게 되니?","ans":"How do you spell your name?","extra":["does"]}},{"lesson":5,"pos":2,"n":3,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ko":"너는 어느 나라에서 왔니?","ans":"Where are you from?","extra":["is"]}},{"lesson":5,"pos":3,"n":0,"kind":"mwbank","tag":"write","payload":{"tag":"write","k":"mwbank","lines":["My name is {}.","{}.","I'm from {}."],"ans":["Max","M-A-X","Brazil"],"extra":["Leo","France"],"blankHints":["영웅의 이름이에요.","이름의 철자를 알파벳 하나씩 말해요.","나라 이름이에요."]}},{"lesson":5,"pos":3,"n":1,"kind":"mwbank","tag":"write","payload":{"tag":"write","k":"mwbank","lines":["My name is {}.","{}.","I'm from {}."],"ans":["Zia","Z-I-A","Egypt"],"extra":["Kai","Korea"],"blankHints":["영웅의 이름이에요.","이름의 철자를 알파벳 하나씩 말해요.","나라 이름이에요."]}},{"lesson":5,"pos":4,"n":0,"kind":"mfree","tag":"write","payload":{"tag":"write","k":"mfree","topic":"brazil","topicLabel":"나의 영웅","lines":["My name is {}.","{}.","I'm from {}."],"lineHints":["나의 영웅 이름을 써요. (예: Max)","영웅 이름의 철자를 알파벳 하나씩 - 로 이어 써요. (예: M-A-X)","나라 이름은 대문자로 시작해요. (예: Brazil)"],"hint":["My name is Max."]}},{"lesson":5,"pos":4,"n":1,"kind":"mfree","tag":"write","payload":{"tag":"write","k":"mfree","topic":"egypt","topicLabel":"나의 영웅","lines":["My name is {}.","{}.","I'm from {}."],"lineHints":["나의 영웅 이름을 써요. (예: Max)","영웅 이름의 철자를 알파벳 하나씩 - 로 이어 써요. (예: M-A-X)","나라 이름은 대문자로 시작해요. (예: Brazil)"],"hint":["My name is Zia."]}},{"lesson":5,"pos":5,"n":0,"kind":"present","tag":"write","payload":{"tag":"write","k":"present","text":["My name is [[Max]].","[[M-A-X]].","I'm from [[Brazil]].","Nice to meet you."]}},{"lesson":6,"pos":5,"n":0,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ans":"Where are you from, Mina?","extra":["is"]}},{"lesson":6,"pos":5,"n":1,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ans":"I'm from Thailand.","extra":["in"]}},{"lesson":6,"pos":5,"n":2,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ans":"How do you spell your name?","extra":["say"]}},{"lesson":6,"pos":5,"n":3,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ans":"Nice to meet you, too.","extra":["see"]}},{"lesson":6,"pos":5,"n":4,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ans":"I'm from the U.S.","extra":["a"]}},{"lesson":6,"pos":5,"n":5,"kind":"sscram","tag":"write","payload":{"tag":"write","k":"sscram","ans":"My name is Tom.","extra":["am"]}},{"lesson":6,"pos":12,"n":0,"kind":"sbuild","tag":"write","payload":{"tag":"write","k":"sbuild","ko":"레오, 너는 어느 나라에서 왔니?","ans":"Where are you from, Leo?","starter":"Where"}},{"lesson":6,"pos":12,"n":1,"kind":"sbuild","tag":"write","payload":{"tag":"write","k":"sbuild","ko":"나는 이집트에서 왔어.","ans":"I'm from Egypt.","alts":["I am from Egypt."],"starter":"I'm"}},{"lesson":6,"pos":12,"n":2,"kind":"sbuild","tag":"write","payload":{"tag":"write","k":"sbuild","ko":"내 이름은 카이야.","ans":"My name is Kai.","starter":"My"}},{"lesson":6,"pos":12,"n":3,"kind":"sbuild","tag":"write","payload":{"tag":"write","k":"sbuild","ko":"너의 이름은 철자가 어떻게 되니?","ans":"How do you spell your name?","starter":"How"}}]$j$::jsonb) as x(lesson int, pos int, n int, kind text, tag text, payload jsonb);
  select count(*) into v_miss from _r d where not exists (select 1 from flow_steps s join flow_lessons fl on fl.id = s.lesson_id where fl.unit_id = v_unit and fl.no = d.lesson and s.pos = d.pos and s.kind = d.kind);
  if v_miss > 0 then raise exception 'L1 revise: % item(s) do not match a flow step', v_miss; end if;
  delete from items i using flow_steps s join flow_lessons fl on fl.id = s.lesson_id
   where i.step_id = s.id and fl.unit_id = v_unit and (fl.no, s.pos) in (select distinct lesson, pos from _r);
  get diagnostics v_del = row_count;
  insert into items(unit_id, lesson, act_idx, level, template, tag, payload, status, step_id, created_at)
  select v_unit, d.lesson, d.pos, 'CORE', d.kind, d.tag, d.payload, 'draft', s.id, now() + (d.n * interval '1 millisecond')
    from _r d join flow_lessons fl on fl.unit_id = v_unit and fl.no = d.lesson join flow_steps s on s.lesson_id = fl.id and s.pos = d.pos;
  get diagnostics v_n = row_count;
  if v_n <> (select count(*) from _r) then raise exception 'L1 revise: inserted % of %', v_n, (select count(*) from _r); end if;
  raise notice 'L1 revise: deleted %, inserted % (draft)', v_del, v_n;
  raise notice 'L1 items total: % (draft %)', (select count(*) from items where unit_id = v_unit), (select count(*) from items where unit_id = v_unit and status = 'draft');
end $do$;
